import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import React from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { loadTypeScriptModule } from "./helpers/load-typescript.mjs";

// Fixture generated by the actual Python engine for the standard wardrobe.
const fixture = JSON.parse(readFileSync(new URL("./fixtures/wardrobe-calculation.json", import.meta.url), "utf8"));
const { calculateWardrobe, formatExactDecimal, isWardrobeCalculationResult } = loadTypeScriptModule("src/features/furniture/calculate-wardrobe.ts");
const { WardrobeCalculationDetails } = loadTypeScriptModule("src/features/furniture/wardrobe-calculation.tsx");

test("decimal formatting preserves every significant digit without numeric conversion", () => {
  assert.equal(formatExactDecimal("397.500"), "397,5");
  assert.equal(formatExactDecimal("6.162224"), "6,162224");
  assert.equal(formatExactDecimal("0.793410"), "0,79341");
  assert.equal(formatExactDecimal("12345678901234567890.123456789"), "12345678901234567890,123456789");
});

test("the Python response contract is accepted and invalid decimal representations are rejected", () => {
  assert.equal(isWardrobeCalculationResult(fixture), true);
  const numericArea = structuredClone(fixture);
  numericArea.totals.total_pal_area_m2 = 6.162224;
  assert.equal(isWardrobeCalculationResult(numericArea), false);
  const invalidDimension = structuredClone(fixture);
  invalidDimension.panels[0].length_mm = "NaN";
  assert.equal(isWardrobeCalculationResult(invalidDimension), false);
  const duplicatePanel = structuredClone(fixture);
  duplicatePanel.panels.push(duplicatePanel.panels[0]);
  assert.equal(isWardrobeCalculationResult(duplicatePanel), false);
});

test("the API client sends only explicitly confirmed configuration as JSON", async context => {
  let captured;
  context.mock.method(globalThis, "fetch", async (url, options) => {
    captured = { url, options };
    return Response.json(fixture);
  });
  const configuration = Object.freeze({ ...fixture.input_configuration });
  const result = await calculateWardrobe(configuration, new AbortController().signal);
  assert.ok(captured.url.endsWith("/api/v1/furniture/calculate"));
  assert.equal(captured.options.headers["Content-Type"], "application/json");
  assert.deepEqual(JSON.parse(captured.options.body), { configuration, confirmed: true });
  assert.equal(result.totals.total_pal_area_m2, "6.162224");
});

test("responses for a different configuration are rejected", async context => {
  const mismatched = structuredClone(fixture);
  mismatched.input_configuration.width_mm = 801;
  context.mock.method(globalThis, "fetch", async () => Response.json(mismatched));
  await assert.rejects(calculateWardrobe(fixture.input_configuration, new AbortController().signal), /nu corespunde/);
});

test("validation and network errors provide recoverable messages", async context => {
  const signal = new AbortController().signal;
  const fetchMock = context.mock.method(globalThis, "fetch", async () => Response.json({}, { status: 422 }));
  await assert.rejects(calculateWardrobe(fixture.input_configuration, signal), /configurare/);
  fetchMock.mock.mockImplementation(async () => Response.json({}, { status: 500 }));
  await assert.rejects(calculateWardrobe(fixture.input_configuration, signal), /Încearcă din nou/);
  fetchMock.mock.mockImplementation(async () => { throw new Error("offline"); });
  await assert.rejects(calculateWardrobe(fixture.input_configuration, signal), /conexiunea/);
});

test("cancelled requests preserve their abort state", async context => {
  const controller = new AbortController();
  controller.abort();
  context.mock.method(globalThis, "fetch", async () => { throw new DOMException("Aborted", "AbortError"); });
  await assert.rejects(calculateWardrobe(fixture.input_configuration, controller.signal), { name: "AbortError" });
});

test("result rendering includes exact areas, separated materials and an accessible cutting table", () => {
  const markup = renderToStaticMarkup(React.createElement(WardrobeCalculationDetails, { result: fixture }));
  assert.match(markup, /6,162224/);
  assert.match(markup, /HDF separat/);
  assert.match(markup, /1,6/);
  assert.match(markup, /764 × 550/);
  assert.match(markup, /PAL · 18 mm/);
  assert.match(markup, /HDF · 3 mm/);
  assert.match(markup, /tabindex="0"/);
  assert.match(markup, /Suprafața fiecărui rând include cantitatea/);
  assert.equal((markup.match(/<tr>/g) || []).length, fixture.panels.length + 1);
  assert.ok(markup.includes(fixture.construction_profile.name));
  for (const assumption of fixture.construction_profile.assumptions) assert.ok(markup.includes(assumption));
});

test("new estimate sections render exact net lengths and preliminary hardware labels", () => {
  const markup = renderToStaticMarkup(React.createElement(WardrobeCalculationDetails, { result: fixture }));
  assert.match(markup, /Canturi ABS/);
  assert.match(markup, /17,392/);
  assert.match(markup, /ABS 0,4 mm/);
  assert.match(markup, /Total net de cant/);
  assert.match(markup, /Adaos de aprovizionare separat · 0 m/);
  assert.match(markup, /Feronerie/);
  assert.match(markup, /Estimare preliminară/);
  assert.match(markup, /Total elemente · 70 buc/);
  assert.ok((markup.match(/<details/g) || []).length >= 4);
  assert.ok(!markup.includes("<details open"));
  for (const item of fixture.hardware.items) {
    assert.ok(markup.includes(item.name));
    assert.ok(markup.includes(item.calculation_rule));
  }
  assert.ok(markup.includes(fixture.edge_banding.edge_convention));
});

test("edge details and hardware must be complete and match the cutting panel metadata", () => {
  for (const mutate of [
    response => { delete response.edge_banding; },
    response => { delete response.hardware; },
    response => { response.edge_banding.totals_by_type.abs_2_total_m = 17.392; },
    response => { response.edge_banding.panel_edges[0].edges.pop(); },
    response => { response.edge_banding.panel_edges[0].quantity = 1; },
    response => { response.edge_banding.panel_edges[0].edges[0].banding_type = "abs_2"; },
    response => { response.panels.find(panel => panel.material === "HDF").edges = response.panels[0].edges; },
    response => { response.hardware.items[0].quantity = -1; },
    response => { response.hardware.items.pop(); },
  ]) {
    const invalid = structuredClone(fixture);
    mutate(invalid);
    assert.equal(isWardrobeCalculationResult(invalid), false);
  }
});

test("a partial calculation response is rejected instead of displayed", async context => {
  const partial = structuredClone(fixture);
  delete partial.hardware;
  context.mock.method(globalThis, "fetch", async () => Response.json(partial));
  await assert.rejects(calculateWardrobe(fixture.input_configuration, new AbortController().signal), /nu este valid/);
});
